"""Тести для завантаження та валідації CSV-файлів."""from pathlib import Pathimport pytestfrom kzp_lab06.errors import DataErrorfrom kzp_lab06.loader import load_recordsdef test_load_valid_records_with_comma(tmp_path: Path) -> None:    """Перевіряє коректне читання записів, включно з комою в назві."""    csv_file = tmp_path / "movies.csv"    csv_file.write_text(        "title,director,year,duration,rating\n"        '"Гаррі Поттер, частина 1",Кріс Коламбус,2001,152,7.6\n'        "Довбуш,Олесь Санін,2023,122,8.0\n",        encoding="utf-8",    )    records = load_records(csv_file)    assert len(records) == 2    assert records[0] == {        "title": "Гаррі Поттер, частина 1",        "director": "Кріс Коламбус",        "year": 2001,        "duration": 152,        "rating": 7.6,    }    assert records[1]["rating"] == 8.0def test_load_empty_dataset_with_header(tmp_path: Path) -> None:    """Перевіряє, що CSV лише із заголовком повертає порожній список."""    csv_file = tmp_path / "empty.csv"    csv_file.write_text("title,director,year,duration,rating\n", encoding="utf-8")    assert load_records(csv_file) == []def test_load_rejects_missing_column(tmp_path: Path) -> None:    """Перевіряє відхилення CSV без обов'язкового стовпця."""    csv_file = tmp_path / "bad_header.csv"    csv_file.write_text(        "title,director,year,duration\nДовбуш,Олесь Санін,2023,122\n", encoding="utf-8"    )    with pytest.raises(DataError, match="заголовок"):        load_records(csv_file)def test_load_rejects_invalid_number_with_cause(tmp_path: Path) -> None:    """Перевіряє номер рядка, назву поля та збереження першопричини."""    csv_file = tmp_path / "bad_number.csv"    csv_file.write_text(        "title,director,year,duration,rating\nДовбуш,Олесь Санін,2023,abc,8.0\n",        encoding="utf-8",    )    with pytest.raises(DataError, match="Рядок 2.*duration") as exc_info:        load_records(csv_file)    assert isinstance(exc_info.value.__cause__, ValueError)def test_load_rejects_missing_value_in_row(tmp_path: Path) -> None:    """Перевіряє відхилення рядка з порожнім або відсутнім значенням."""    csv_file = tmp_path / "missing_val.csv"    csv_file.write_text(        "title,director,year,duration,rating\nДовбуш,Олесь Санін,2023,122,\n",        encoding="utf-8",    )    with pytest.raises(DataError, match="Рядок 2.*rating"):        load_records(csv_file)def test_load_rejects_negative_duration(tmp_path: Path) -> None:    """Перевіряє відхилення недодатної тривалості."""    csv_file = tmp_path / "neg.csv"    csv_file.write_text(        "title,director,year,duration,rating\nДовбуш,Олесь Санін,2023,-10,8.0\n",        encoding="utf-8",    )    with pytest.raises(DataError, match="Рядок 2.*duration"):        load_records(csv_file)def test_load_missing_file_preserves_oserror(tmp_path: Path) -> None:    """Перевіряє обгортання OSError у DataError."""    with pytest.raises(DataError) as exc_info:        load_records(tmp_path / "not_found.csv")    assert isinstance(exc_info.value.__cause__, OSError)